<?php
namespace App\Http\Middleware;
use Illuminate\Http\Request;
use Inertia\Middleware;
class HandleInertiaRequests extends Middleware{protected $rootView='app';public function share(Request$request):array{return[...parent::share($request),'csrfToken'=>$request->session()->token(),'auth'=>['user'=>$request->user()?->only('id','name','email','account_type','role')],'preferences'=>fn()=>($request->user()?->meta['preferences']??['slideshow_interval'=>5,'slideshow_loop'=>false,'email_notifications'=>true]),'notificationUnreadCount'=>fn()=>($user=$request->user())&&\Schema::hasTable('notifications')?app(\App\Services\Notifications\NotificationAccess::class)->query($user)->whereNull('read_at')->count():0,'permissions'=>['createGroups'=>fn()=>($user=$request->user())?$user->can('create',\App\Models\Group::class):false],'analyticsAccess'=>fn()=>($user=$request->user())?$this->analyticsAccess($user):null,'settingsNavigation'=>fn()=>app(\App\Services\Settings\SettingsNavigation::class)->for($request->user()),'flash'=>['success'=>fn()=>$request->session()->get('success'),'error'=>fn()=>$request->session()->get('error')]];}private function analyticsAccess($user):array{$service=app(\App\Services\Analytics\AnalyticsAuthorization::class);$context=$service->context($user);$eligible=$service->roleEligible($user);$enabled=$context&&$service->entitled($context);return['eligible'=>$eligible,'enabled'=>(bool)$enabled,'href'=>$enabled?route('analytics'):route('settings.subscription',['feature'=>'analytics']),'label'=>$enabled?null:'Upgrade'];}}
